from taf.internal.managed.telnet import ManagedCliTelnetConnection
from taf.internal.portforwarding import Portforwarding
from .aashell import AaShell


class AaShellFactory(object):
    _available_instances = {}

    def __init__(self, port_forwarding=None, **kwargs):
        super(AaShellFactory, self).__init__(**kwargs)
        if port_forwarding is None:
            port_forwarding = Portforwarding()
        self._port_forwarding = port_forwarding

    def create_aashell(self, host="127.0.0.1", port=15007, hops=None, namespace=None, pod=None, forwarding_port=None):
        """
        Return an AaShell.

        :param str host: (optional) AaShell host ip, default value is "127.0.0.1"
        :param int port: (optional) AaShell port, default value is 15007
        :param dict hops: (optional) host info like host, user, password, pkey, key_filename, proxy, port if port
            forwarding required to reach AaShell host:port service, default is gNB toor4nsn executor details
        :param str namespace: (optional) kubernetes namespace for vCU/vDU
        :param str pod: (optional) kubernetes pod name for vCU/vDU
        :param int forwarding_port: (optional) local port where forwarding will be done (localhost:forwarding_port <-
            host:port). By default it will use 'port'
        :return: AaShell

        In case of vCU/vDU namespace and pod parameter is must, for classical BTS it is not required. Also hops should
        be given accordingly. Please refer usage section for examples.
        """

        if hops is None:
            hops = {}
        hop_config = {
            "host": "192.168.255.129",
            "user": "toor4nsn",
            "password": "oZPS0POrRieRtu",
            "port": 22,
        }
        hop_config.update(hops)
        if ("proxy" not in hop_config) and (namespace and pod):
            hop_config["proxy"] = hops.copy()
        forwarding_port = forwarding_port or 0
        branch_signature = "{forwarding_port}_{hops_signature}{kubectl}_{remote_host}_{remote_port}".format(
            forwarding_port=forwarding_port,
            hops_signature=AaShellFactory._hops_signature(hop_config),
            kubectl="_{namespace}_{pod}".format(namespace=namespace, pod=pod) if (namespace and pod) else "",
            remote_host=host,
            remote_port=port,
        )
        if branch_signature not in self._available_instances:
            hop_list = AaShellFactory._generate_hop_list(self._port_forwarding, hop_config)
            ssh_forwarding_branch = self._port_forwarding.create_ssh_forwarding_branch(
                hops=hop_list,
                forwarding_port=forwarding_port,
                remote_service=self._port_forwarding.create_kubectl_forward_remote_service(
                    namespace=namespace, pod=pod, port=port
                )
                if (namespace and pod)
                else self._port_forwarding.create_remote_service(ip=host, port=port),
            )
            telnet_connection = ManagedCliTelnetConnection(
                host="127.0.0.1", port=lambda: ssh_forwarding_branch.forwarding_port, prompt=b"AaShell> "
            )
            telnet_connection.add_prerequisite(ssh_forwarding_branch)
            self._available_instances[branch_signature] = AaShell(telnet_connection=telnet_connection)
        return self._available_instances[branch_signature]

    @staticmethod
    def _generate_hop_list(port_forwarding, hops):
        hops = hops.copy()
        proxy = hops.pop("proxy", None)
        hop = [port_forwarding.create_ssh_forwardable_hop(**hops)]
        return AaShellFactory._generate_hop_list(port_forwarding, proxy) + hop if proxy else hop

    @staticmethod
    def _hops_signature(hops):
        hops_signature = "{host}_{port}".format(host=hops.get("host"), port=hops.get("port", 22))
        return (
            "{proxy}_{hops_signature}".format(
                proxy=AaShellFactory._hops_signature(hops.get("proxy")), hops_signature=hops_signature
            )
            if hops.get("proxy")
            else hops_signature
        )
